#!/bin/bash\n# verify-tests.sh\n# Verify SkillOS E2E tests setup\n\necho \"🔍 SkillOS E2E Tests - Verification Script\"\necho \"=========================================\"\necho \"\"\n\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m'\n\nCHECKS_PASSED=0\nCHECKS_FAILED=0\n\necho -e \"${BLUE}Checking project setup...${NC}\"\necho \"\"\n\n# Check 1: Node/NPM installed\necho -e \"${BLUE}1. Checking Node.js and NPM...${NC}\"\nif command -v node &> /dev/null && command -v npm &> /dev/null; then\n  NODE_VERSION=$(node -v)\n  NPM_VERSION=$(npm -v)\n  echo -e \"${GREEN}✓ Node.js ${NODE_VERSION} and NPM ${NPM_VERSION} found${NC}\"\n  ((CHECKS_PASSED++))\nelse\n  echo -e \"${RED}✗ Node.js or NPM not found${NC}\"\n  ((CHECKS_FAILED++))\nfi\necho \"\"\n\n# Check 2: Playwright installed\necho -e \"${BLUE}2. Checking Playwright installation...${NC}\"\nif [ -d \"node_modules/@playwright\" ]; then\n  PLAYWRIGHT_VERSION=$(cat package-lock.json 2>/dev/null | grep -A 2 \"@playwright/test\" | grep \"\\\"version\\\"\" | head -1 | cut -d'\"' -f4)\n  echo -e \"${GREEN}✓ Playwright installed (version: ${PLAYWRIGHT_VERSION})${NC}\"\n  ((CHECKS_PASSED++))\nelse\n  echo -e \"${YELLOW}! Playwright not installed. Run: npm install${NC}\"\n  ((CHECKS_FAILED++))\nfi\necho \"\"\n\n# Check 3: Required files exist\necho -e \"${BLUE}3. Checking required files...${NC}\"\nFILES=(\"package.json\" \"playwright.config.js\" \"playwright-tests.js\" \"test-scenarios.js\" \"page-objects.js\" \"test-config.js\")\nfor file in \"${FILES[@]}\"; do\n  if [ -f \"$file\" ]; then\n    echo -e \"${GREEN}✓ $file${NC}\"\n    ((CHECKS_PASSED++))\n  else\n    echo -e \"${RED}✗ $file missing${NC}\"\n    ((CHECKS_FAILED++))\n  fi\ndone\necho \"\"\n\n# Check 4: Test files are readable\necho -e \"${BLUE}4. Checking test file syntax...${NC}\"\nif node -c playwright-tests.js 2>/dev/null; then\n  echo -e \"${GREEN}✓ playwright-tests.js syntax OK${NC}\"\n  ((CHECKS_PASSED++))\nelse\n  echo -e \"${RED}✗ playwright-tests.js has syntax errors${NC}\"\n  ((CHECKS_FAILED++))\nfi\necho \"\"\n\n# Check 5: Backend running\necho -e \"${BLUE}5. Checking if backend is running (localhost:8000)...${NC}\"\nif timeout 2 curl -s http://localhost:8000 &>/dev/null || timeout 2 curl -s http://localhost:8000/docs &>/dev/null; then\n  echo -e \"${GREEN}✓ Backend is running on http://localhost:8000${NC}\"\n  ((CHECKS_PASSED++))\nelse\n  echo -e \"${YELLOW}! Backend not running (port 8000)${NC}\"\n  echo -e \"  ${YELLOW}Start with: cd ../backend && python -m uvicorn main:app --reload --port 8000${NC}\"\n  ((CHECKS_FAILED++))\nfi\necho \"\"\n\n# Check 6: Frontend running\necho -e \"${BLUE}6. Checking if frontend is running (localhost:5173)...${NC}\"\nif timeout 2 curl -s http://localhost:5173 &>/dev/null; then\n  echo -e \"${GREEN}✓ Frontend is running on http://localhost:5173${NC}\"\n  ((CHECKS_PASSED++))\nelse\n  echo -e \"${YELLOW}! Frontend not running (port 5173)${NC}\"\n  echo -e \"  ${YELLOW}Start with: cd ../frontend && npm run dev${NC}\"\n  ((CHECKS_FAILED++))\nfi\necho \"\"\n\n# Check 7: NPM scripts configured\necho -e \"${BLUE}7. Checking NPM scripts...${NC}\"\nif grep -q '\"test\": \"playwright test\"' package.json; then\n  echo -e \"${GREEN}✓ NPM test scripts configured${NC}\"\n  echo -e \"  Available: npm run test, npm run test:ui, npm run test:debug\"\n  ((CHECKS_PASSED++))\nelse\n  echo -e \"${RED}✗ NPM test scripts not configured${NC}\"\n  ((CHECKS_FAILED++))\nfi\necho \"\"\n\n# Summary\necho \"==================================\"\necho -e \"${BLUE}Summary:${NC}\"\necho -e \"${GREEN}✓ Passed: $CHECKS_PASSED${NC}\"\nif [ $CHECKS_FAILED -gt 0 ]; then\n  echo -e \"${RED}✗ Failed: $CHECKS_FAILED${NC}\"\nelse\n  echo -e \"${GREEN}✗ Failed: 0${NC}\"\nfi\necho \"\"\n\nif [ $CHECKS_FAILED -eq 0 ]; then\n  echo -e \"${GREEN}🎉 Everything is ready!${NC}\"\n  echo \"\"\n  echo -e \"${BLUE}You can now run:${NC}\"\n  echo -e \"  ${GREEN}npm run test${NC}          - Run all tests\"\n  echo -e \"  ${GREEN}npm run test:ui${NC}       - Run with UI\"\n  echo -e \"  ${GREEN}npm run test:debug${NC}    - Debug mode\"\n  echo \"\"\nelse\n  echo -e \"${YELLOW}Please fix the above issues before running tests${NC}\"\n  echo \"\"\n  echo -e \"${BLUE}Checklist:${NC}\"\n  [ ! -d \"node_modules/@playwright\" ] && echo \"  [ ] Run: npm install\"\n  ! timeout 2 curl -s http://localhost:8000 &>/dev/null && echo \"  [ ] Start backend: cd ../backend && python -m uvicorn main:app --reload --port 8000\"\n  ! timeout 2 curl -s http://localhost:5173 &>/dev/null && echo \"  [ ] Start frontend: cd ../frontend && npm run dev\"\nfi\n\necho \"\"\necho \"📖 For more info, see README.md or QUICKSTART.md\"\n"